const frame = (bg,content) => `<svg viewBox="0 0 700 310" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><rect width="700" height="310" fill="${bg}"/>${content}</svg>`;
const cloud=(x,y,s=1)=>`<g fill="#fffdf1" opacity=".75" transform="translate(${x} ${y}) scale(${s})"><ellipse cx="50" cy="25" rx="50" ry="18"/><circle cx="30" cy="20" r="20"/><circle cx="58" cy="14" r="24"/></g>`;
const bird=(x,y)=>`<path d="M${x} ${y}q8 -9 16 0q8 -9 16 0" fill="none" stroke="#4b7768" stroke-width="3" stroke-linecap="round"/>`;
export function sceneArt(index,level,desertLabel='DESERT'){const empty=level===2,half=level===1;
if(index===0)return frame('#b5ddca',`${cloud(80,25,.75)}${cloud(455,27,.9)}${bird(340,55)}<circle cx="614" cy="56" r="29" fill="#f9d675"/><path d="M0 176Q130 143 260 171T500 165T700 165V310H0" fill="#84ba92"/><path d="M0 231Q190 195 365 226T700 214V310H0" fill="#a5c978"/><g fill="#609c70"><circle cx="48" cy="139" r="40"/><circle cx="88" cy="144" r="33"/><rect x="61" y="141" width="11" height="64" fill="#a8784e"/><circle cx="650" cy="140" r="40"/><rect x="645" y="145" width="11" height="56" fill="#a8784e"/></g><g transform="translate(85 92)"><path d="M0 105L38 0l38 105M12 74h53M143 105L180 0l38 105M156 74h52" stroke="#d76c4c" stroke-width="8" fill="none"/><path d="M38 0h142" stroke="#d76c4c" stroke-width="9"/><path d="M95 2v60m39-60v60" stroke="#766153" stroke-width="3"/><path d="M85 63h20m20 0h20" stroke="#5c7165" stroke-width="8"/></g><ellipse cx="397" cy="243" rx="184" ry="47" fill="#758a5d" opacity=".2"/><path d="M229 209l63-31h190l54 31-15 50H242z" fill="#9c6541"/><path d="M242 207l58-23h174l48 23-12 39H254z" fill="${empty?'#ab8756':half?'#d6aa63':'#f4d083'}"/><path d="M242 207l12 39m268-39l-12 39" stroke="#704b39" stroke-width="5"/><path d="M260 235q70 ${empty?'-1':'-18'} 130 -6t119 2" fill="none" stroke="${empty?'#94754d':'#e5b86e'}" stroke-width="4"/><g transform="translate(334 194) rotate(-12)"><path d="M0 24h45l-7 18H8z" fill="#e47c53"/><path d="M7 24q13-16 30 0" fill="none" stroke="#fff1cf" stroke-width="3"/></g><path d="M430 211l27-23m-22 28l6-17" stroke="#7195a7" stroke-width="6" stroke-linecap="round"/><circle cx="267" cy="235" r="4" fill="#faf1ca"/><circle cx="479" cy="221" r="3" fill="#faf1ca"/>`);
if(index===1)return frame('#a4d9d7',`${cloud(95,28,.7)}${cloud(480,36,.8)}<circle cx="605" cy="60" r="33" fill="#f4d071"/><path d="M0 140q90 -10 180 0t180 0t180 0t160 0v100H0" fill="#6eb7b4"/><path d="M0 177q130 -12 230 1t230 0t240 0v18H0" fill="#e8f4d9"/><path d="M0 192Q300 165 700 203V310H0" fill="${empty?'#b2ab89':half?'#e2bd78':'#f3d491'}"/><path d="M0 240q150 -20 300 0t400 0" fill="none" stroke="#e4bd7e" stroke-width="5"/><g transform="translate(155 112)"><path d="M90 0v120" stroke="#6e6252" stroke-width="5"/><path d="M18 48q72 -89 144 0z" fill="#ee8b68"/><path d="M48 48q42 -89 84 0" fill="#f7dba6"/></g><g transform="translate(375 193)"><path d="M0 35l52 -27 60 30M11 30l-12 35m90 -40l30 38" stroke="#aa774e" stroke-width="7" fill="none"/><path d="M12 27l41-21 48 32-47 19z" fill="#f2a17d"/></g><path d="M550 226q22-25 44 0" fill="none" stroke="#6d9e83" stroke-width="8"/><circle cx="572" cy="216" r="11" fill="#d08e62"/>`);
if(index===2)return frame('#f3c494',`${cloud(110,36,.75)}${bird(445,48)}<circle cx="581" cy="65" r="37" fill="#ffe39a"/><path d="M0 205Q130 92 265 180Q380 85 520 181Q605 125 700 179V310H0" fill="#dda45e"/><path d="M0 238Q160 160 340 229Q540 149 700 224V310H0" fill="${empty?'#bc956f':half?'#dfb77f':'#efca88'}"/><g fill="#679260"><rect x="117" y="165" width="15" height="75" rx="7"/><path d="M120 207q-24 0-24-24v-10h10v10q0 12 14 12m11 2q23 0 23-24v-7h-10v7q0 12-13 12"/></g><g transform="translate(408 174)" fill="#9c7556"><ellipse cx="50" cy="39" rx="47" ry="25"/><path d="M30 23q6-40 19-2q7-38 18 3M13 49l-3 50h9l8-45m38-5l7 50h9l-3-55m3-23l21-29 11 2-12 41z"/><circle cx="110" cy="5" r="13"/></g><g transform="translate(250 193)"><rect x="30" y="6" width="7" height="75" fill="#987152"/><rect width="100" height="38" rx="4" fill="#f8e6b7" stroke="#987152" stroke-width="4"/><text x="50" y="25" fill="#8c7657" font-size="12" text-anchor="middle" font-family="sans-serif" font-weight="bold">${desertLabel}</text></g>`);
return frame('#8ecbc9',`<path d="M0 0h700v55Q600 75 500 50T300 48T0 48" fill="#a9dfd2"/><path d="M115 0l-45 220h85L190 0M390 0l-30 220h60L455 0" fill="#d1eee0" opacity=".25"/><path d="M0 236q130-50 300-2t400-5v81H0" fill="${empty?'#889c89':half?'#c9ba8e':'#e9cf96'}"/><g fill="#689e91"><path d="M43 280q25-75 14-101q-25 30-14 101M84 285q-10-60 7-85q20 35-7 85M586 279q-5-85 20-103q13 50-20 103M632 280q-8-50 15-75q12 37-15 75"/></g><g transform="translate(220 97)" fill="#f19b72"><ellipse cx="55" cy="25" rx="42" ry="23"/><path d="M20 25L0 5v40z"/><circle cx="78" cy="21" r="4" fill="#fff"/><circle cx="79" cy="21" r="2" fill="#344e48"/></g><g transform="translate(430 142) scale(.7)" fill="#edc15f"><ellipse cx="55" cy="25" rx="42" ry="23"/><path d="M20 25L0 5v40z"/><circle cx="78" cy="21" r="4" fill="#fff"/><circle cx="79" cy="21" r="2" fill="#344e48"/></g><g fill="none" stroke="#cbeae0" stroke-width="3"><circle cx="325" cy="130" r="7"/><circle cx="340" cy="100" r="10"/><circle cx="350" cy="67" r="6"/></g>`)}
export function houseArt(stage){return frame('#dcead4',`${cloud(30,25,.7)}${cloud(500,30,.8)}<circle cx="560" cy="63" r="30" fill="#f6cf73"/><path d="M0 235Q320 180 700 236V310H0" fill="#b5cf8e"/><ellipse cx="352" cy="266" rx="175" ry="24" fill="#80a875" opacity=".4"/><path d="M175 132L350 37l175 95v121H175z" fill="#c5e8e4" stroke="#567d74" stroke-width="7"/><path d="M164 136L350 34l187 102" fill="none" stroke="#4d7268" stroke-width="12" stroke-linecap="round" stroke-linejoin="round"/><path d="M216 130h268v123H216zM350 42v210M216 174h268" fill="none" stroke="#7fa9a0" stroke-width="4"/><path d="M310 252v-82h79v82" fill="#f9efce" fill-opacity=".5" stroke="#567d74" stroke-width="5"/><circle cx="374" cy="213" r="4" fill="#567d74"/>${stage>0?'<g transform="translate(394 198)" fill="#f8f5df" stroke="#718f81" stroke-width="3"><rect x="10" y="0" width="34" height="24" rx="5"/><path d="M8 24h39q0 22-17 22T8 24z"/><path d="M22 46h16v9H22z"/></g>':''}${stage>1?'<path d="M258 131l18 25-10 15 19 20-7 25" fill="none" stroke="#668a85" stroke-width="3"/><path d="M473 166l-14 17 13 13-15 14" fill="none" stroke="#668a85" stroke-width="3"/>':''}<path d="M118 92l5 11 11 5-11 5-5 11-5-11-11-5 11-5zM564 154l4 8 8 4-8 4-4 8-4-8-8-4 8-4z" fill="#fffdf2"/>`)}
